WITH remaining_keys AS (SELECT carrier, status FROM shipments INTERSECT ALL SELECT carrier, status FROM shipments WHERE cost BETWEEN 30 AND 85), verified AS (SELECT s.* FROM shipments s INNER JOIN remaining_keys k ON s.carrier = k.carrier AND s.status = k.status) SELECT s.order_id, s.carrier, s.shipped_date, s.delivered_date, s.cost, s.status, (SELECT MIN(t2.quantity) FROM order_items t2 WHERE t2.order_id = s.order_id) AS min_order_item_quantity FROM verified s ORDER BY delivered_date DESC NULLS LAST;
